module freq_divbyfrac #(
    parameter MUL2_DIV_CLK = 7
) (
    input               rst_n,
    input               clk,
    output              clk_div
);

    reg [3:0] cnt;
    reg div_clk_ave;
    reg div_clk_adjust;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 0;
        end else begin
            if (cnt == MUL2_DIV_CLK-1) begin
                cnt <= 0;
            end else begin
                cnt <= cnt + 1;
            end
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            div_clk_ave <= 0;
        end else begin
            if ((cnt == 0 || cnt == 4)) begin
                div_clk_ave <= 1;
            end else begin
                div_clk_ave <= 0;
            end
        end
    end

    always @(negedge clk or negedge rst_n) begin
        if (!rst_n) begin
            div_clk_adjust <= 0;
        end else begin
            if ((cnt == 1 || cnt == 4)) begin
                div_clk_adjust <= 1;
            end else begin
                div_clk_adjust <= 0;
            end
        end
    end

    assign clk_div = div_clk_adjust | div_clk_ave;

endmodule
